import logging
import sys

import torch
import triton
import triton.language as tl
from torch import Tensor

from flag_gems.runtime import torch_device_fn
from flag_gems.runtime.backend._enflame.gcu400.ops.batch_norm import (
    batch_norm,
    make_3d_for_bn,
)
from flag_gems.utils import libentry

logger = logging.getLogger(__name__)

TILE_BUDGET = 16384
BLOCK_M_CAP = 2048
NUM_WARPS = 8
LOOP_STAGES = 1
LAUNCH_STAGES = 2
WELFORD_MODE = 1
SHAPE_CHECK = 1

# gcu400 pipeline knobs: below PIPELINE_MIN_ELEMENTS per-channel work is small
# enough that one fused kernel launch beats the partial+apply two-launch scheme;
# above it the (C, parts) 2D grid recovers the 48-SPU parallelism that the
# single-CTA-per-channel fused kernel cannot reach when channels are few.
# Masked (non power-of-2-divisible spatial) loads stay <= MASKED_LANE_CAP lanes
# and never use `other=`: large masked+other loads silently corrupt on gcu400.
PIPELINE_MIN_ELEMENTS = 1 << 19
PARTIAL_BLOCK_CAP = 16384
APPLY_BLOCK_CAP = 32768
MASKED_LANE_CAP = 8192
MAX_GRID_Y = 255
TARGET_PROGRAM_WAVES = 2
SPU_COUNT = 48
PARTIAL_WARPS = 16
APPLY_WARPS = 16


@libentry()
@triton.jit(do_not_specialize=["batch_dim", "spatial_dim", "momentum", "eps"])
def _nbn_fused_kernel(
    input_pointer,
    weight_pointer,
    bias_pointer,
    mean_pointer,
    inv_std_pointer,
    output_pointer,
    running_mean_pointer,
    running_var_pointer,
    batch_dim,
    spatial_dim,
    input_batch_stride,
    input_feat_stride,
    input_spatial_stride,
    output_batch_stride,
    output_feat_stride,
    output_spatial_stride,
    momentum,
    eps,
    IS_TRAIN: tl.constexpr,
    HAS_RUNNING: tl.constexpr,
    BLOCK_M: tl.constexpr,
    BLOCK_N: tl.constexpr,
    LOOP_STAGES: tl.constexpr,
    WELFORD_MODE: tl.constexpr,
):
    """One channel per CTA: first pass computes mean / variance, second pass normalizes and writes out.

    no_stats_out has no persistent running stats, so the dedicated kernel needs no
    running_mean/running_var reads or momentum updates from the training branch; statistics always accumulate in fp32.
    """
    feat_pid = tl.program_id(axis=0)
    first_moment = tl.zeros((BLOCK_M, BLOCK_N), dtype=tl.float32)
    second_moment = tl.zeros((BLOCK_M, BLOCK_N), dtype=tl.float32)
    element_count = tl.zeros((BLOCK_M, BLOCK_N), dtype=tl.int32)
    num_steps_m = tl.cdiv(batch_dim, BLOCK_M)
    num_steps_n = tl.cdiv(spatial_dim, BLOCK_N)
    num_elements = batch_dim * spatial_dim

    if IS_TRAIN:
        for m_step in tl.range(0, num_steps_m, num_stages=LOOP_STAGES):
            for n_step in range(0, num_steps_n):
                batch_offset = m_step * BLOCK_M + tl.arange(0, BLOCK_M)
                spatial_offset = n_step * BLOCK_N + tl.arange(0, BLOCK_N)
                element_mask = (batch_offset[:, None] < batch_dim) & (
                    spatial_offset[None, :] < spatial_dim
                )
                input_tile_pointer = (
                    input_pointer
                    + input_feat_stride * feat_pid
                    + input_batch_stride * batch_offset[:, None]
                    + input_spatial_stride * spatial_offset[None, :]
                )
                input_tile = tl.load(input_tile_pointer, mask=element_mask).to(
                    tl.float32
                )
                step_index = m_step * num_steps_n + n_step + 1
                if WELFORD_MODE == 0:
                    updated_mean = tl.where(
                        element_mask,
                        first_moment + (input_tile - first_moment) / step_index,
                        first_moment,
                    )
                    updated_second = tl.where(
                        element_mask,
                        second_moment
                        + (input_tile - updated_mean) * (input_tile - first_moment),
                        second_moment,
                    )
                else:
                    updated_mean = tl.where(
                        element_mask, first_moment + input_tile, first_moment
                    )
                    updated_second = tl.where(
                        element_mask,
                        second_moment + input_tile * input_tile,
                        second_moment,
                    )
                element_count += element_mask.to(tl.int32)
                first_moment = updated_mean
                second_moment = updated_second

        if WELFORD_MODE == 0:
            final_mean = tl.sum(first_moment * element_count) / num_elements
            variance = (
                tl.sum(
                    second_moment
                    + element_count
                    * (first_moment - final_mean)
                    * (first_moment - final_mean)
                )
                / num_elements
            )
        else:
            final_mean = tl.sum(first_moment) / num_elements
            variance = tl.maximum(
                tl.sum(second_moment) / num_elements - final_mean * final_mean, 0.0
            )
        inv_std = 1.0 / tl.sqrt(variance + eps)
        tl.store(feat_pid + mean_pointer, final_mean)
        tl.store(feat_pid + inv_std_pointer, inv_std)

        if HAS_RUNNING:
            running_mean = tl.load(feat_pid + running_mean_pointer).to(tl.float32)
            running_var = tl.load(feat_pid + running_var_pointer).to(tl.float32)
            tl.store(
                feat_pid + running_mean_pointer,
                (1 - momentum) * running_mean + momentum * final_mean,
            )
            tl.store(
                feat_pid + running_var_pointer,
                (1 - momentum) * running_var
                + momentum * variance * num_elements / (num_elements - 1),
            )
        mean = final_mean
    else:
        mean = tl.load(feat_pid + running_mean_pointer).to(tl.float32)
        running_var = tl.load(feat_pid + running_var_pointer).to(tl.float32)
        inv_std = 1.0 / tl.sqrt(running_var + eps)
        tl.store(feat_pid + mean_pointer, mean)
        tl.store(feat_pid + inv_std_pointer, inv_std)

    if weight_pointer:
        weight = tl.load(feat_pid + weight_pointer).to(tl.float32)
    else:
        weight = 1.0
    if bias_pointer:
        bias = tl.load(feat_pid + bias_pointer).to(tl.float32)
    else:
        bias = 0.0

    for m_step in tl.range(0, num_steps_m, num_stages=LOOP_STAGES):
        for n_step in range(0, num_steps_n):
            batch_offset = m_step * BLOCK_M + tl.arange(0, BLOCK_M)
            spatial_offset = n_step * BLOCK_N + tl.arange(0, BLOCK_N)
            element_mask = (batch_offset[:, None] < batch_dim) & (
                spatial_offset[None, :] < spatial_dim
            )
            input_tile_pointer = (
                input_pointer
                + input_feat_stride * feat_pid
                + input_batch_stride * batch_offset[:, None]
                + input_spatial_stride * spatial_offset[None, :]
            )
            output_tile_pointer = (
                output_pointer
                + output_feat_stride * feat_pid
                + output_batch_stride * batch_offset[:, None]
                + output_spatial_stride * spatial_offset[None, :]
            )
            input_tile = tl.load(input_tile_pointer, mask=element_mask).to(tl.float32)
            normalized = weight * (input_tile - mean) * inv_std + bias
            tl.store(output_tile_pointer, normalized, mask=element_mask)


@libentry()
@triton.jit(do_not_specialize=["spatial_dim"])
def _nbn_partial_kernel(
    input_pointer,
    partial_sum_pointer,
    partial_sumsq_pointer,
    spatial_dim,
    input_batch_stride,
    input_feat_stride,
    S_TILES: tl.constexpr,
    UNITS: tl.constexpr,
    GRID_P: tl.constexpr,
    BLOCK_S: tl.constexpr,
    EVEN_S: tl.constexpr,
):
    """Per-channel blocked sum / sum-of-squares statistics for contiguous spatial input.

    grid=(C, GRID_P): each program walks (batch, s-tile) as affine units
    unit = part_id, part_id+GRID_P, ...; addresses inside a unit are pure affine.
    `channel_base + b*batch_stride + s_tile*BLOCK_S + arange`, div/mod
    division only happens on per-unit scalars (unit // S_TILES), avoiding a per-element extern wall.
    Partial sums go into a (C, GRID_P) fp32 buffer and the apply kernel merges them.
    The non-EVEN tier masks loads without other (a known gcu400 trap: masked+other with many lanes
    silently yields wrong values); masked lanes are explicitly cleared with where.
    """
    feat_pid = tl.program_id(axis=0)
    part_id = tl.program_id(axis=1)
    acc_sum = tl.zeros((BLOCK_S,), dtype=tl.float32)
    acc_sumsq = tl.zeros((BLOCK_S,), dtype=tl.float32)
    channel_base = input_pointer + input_feat_stride * feat_pid
    for unit in tl.range(part_id, UNITS, GRID_P):
        batch_index = unit // S_TILES
        s_tile = unit % S_TILES
        s_offset = s_tile * BLOCK_S + tl.arange(0, BLOCK_S)
        offset = batch_index * input_batch_stride + s_offset
        if EVEN_S:
            x = tl.load(channel_base + offset).to(tl.float32)
        else:
            s_mask = s_offset < spatial_dim
            x = tl.load(channel_base + offset, mask=s_mask)
            x = tl.where(s_mask, x, 0.0)
        acc_sum += x
        acc_sumsq += x * x
    tl.store(partial_sum_pointer + feat_pid * GRID_P + part_id, tl.sum(acc_sum))
    tl.store(partial_sumsq_pointer + feat_pid * GRID_P + part_id, tl.sum(acc_sumsq))


@libentry()
@triton.jit(do_not_specialize=["numel_per_c", "spatial_dim", "momentum", "eps"])
def _nbn_apply_kernel(
    input_pointer,
    output_pointer,
    weight_pointer,
    bias_pointer,
    save_mean_pointer,
    save_invstd_pointer,
    running_mean_pointer,
    running_var_pointer,
    partial_sum_pointer,
    partial_sumsq_pointer,
    input_batch_stride,
    input_feat_stride,
    output_batch_stride,
    output_feat_stride,
    numel_per_c,
    spatial_dim,
    momentum,
    eps,
    IS_TRAIN: tl.constexpr,
    HAS_RUNNING: tl.constexpr,
    HAS_WEIGHT: tl.constexpr,
    HAS_BIAS: tl.constexpr,
    S_TILES: tl.constexpr,
    UNITS: tl.constexpr,
    GRID_P: tl.constexpr,
    PARTS: tl.constexpr,
    PARTS_P2: tl.constexpr,
    BLOCK_S: tl.constexpr,
    EVEN_S: tl.constexpr,
):
    """Merges the partial statistics and writes the normalized output (stage 2 of the contiguous fast path).

    Each program first merges all partials of its channel into mean/var/inv_std (the partial array
    holds at most MAX_GRID_Y fp32 values, so the repeated merge is negligible), then normalizes its
    own units as (batch, s-tile) affine units. The program with part_id == 0 exclusively writes the
    save stats and running stats, so there are no write-write races.
    """
    feat_pid = tl.program_id(axis=0)
    part_id = tl.program_id(axis=1)

    if IS_TRAIN:
        part_index = tl.arange(0, PARTS_P2)
        part_mask = part_index < PARTS
        partial_sum = tl.load(
            partial_sum_pointer + feat_pid * PARTS + part_index,
            mask=part_mask,
            other=0.0,
        )
        partial_sumsq = tl.load(
            partial_sumsq_pointer + feat_pid * PARTS + part_index,
            mask=part_mask,
            other=0.0,
        )
        mean = tl.sum(partial_sum) / numel_per_c
        variance = tl.maximum(tl.sum(partial_sumsq) / numel_per_c - mean * mean, 0.0)
        inv_std = 1.0 / tl.sqrt(variance + eps)
    else:
        mean = tl.load(feat_pid + running_mean_pointer).to(tl.float32)
        variance = tl.load(feat_pid + running_var_pointer).to(tl.float32)
        inv_std = 1.0 / tl.sqrt(variance + eps)

    if part_id == 0:
        tl.store(feat_pid + save_mean_pointer, mean)
        tl.store(feat_pid + save_invstd_pointer, inv_std)
        if IS_TRAIN and HAS_RUNNING:
            running_mean = tl.load(feat_pid + running_mean_pointer).to(tl.float32)
            running_var = tl.load(feat_pid + running_var_pointer).to(tl.float32)
            tl.store(
                feat_pid + running_mean_pointer,
                (1 - momentum) * running_mean + momentum * mean,
            )
            tl.store(
                feat_pid + running_var_pointer,
                (1 - momentum) * running_var
                + momentum * variance * numel_per_c / (numel_per_c - 1),
            )

    if HAS_WEIGHT:
        weight = tl.load(feat_pid + weight_pointer).to(tl.float32)
    else:
        weight = 1.0
    if HAS_BIAS:
        bias = tl.load(feat_pid + bias_pointer).to(tl.float32)
    else:
        bias = 0.0

    input_base = input_pointer + input_feat_stride * feat_pid
    output_base = output_pointer + output_feat_stride * feat_pid
    for unit in tl.range(part_id, UNITS, GRID_P):
        batch_index = unit // S_TILES
        s_tile = unit % S_TILES
        s_offset = s_tile * BLOCK_S + tl.arange(0, BLOCK_S)
        input_offset = batch_index * input_batch_stride + s_offset
        output_offset = batch_index * output_batch_stride + s_offset
        if EVEN_S:
            x = tl.load(input_base + input_offset).to(tl.float32)
            normalized = weight * (x - mean) * inv_std + bias
            tl.store(output_base + output_offset, normalized)
        else:
            s_mask = s_offset < spatial_dim
            x = tl.load(input_base + input_offset, mask=s_mask)
            normalized = weight * (x - mean) * inv_std + bias
            tl.store(output_base + output_offset, normalized, mask=s_mask)


def _choose_tile(batch_dim, spatial_dim):
    """Picks the tile by power of two and element budget; both axes are at least 2 wide to avoid a 1-D slice layout crash."""
    block_m = max(2, min(BLOCK_M_CAP, triton.next_power_of_2(batch_dim)))
    max_block_n = max(1, TILE_BUDGET // block_m)
    block_n = max(2, min(triton.next_power_of_2(spatial_dim), max_block_n))
    return block_m, triton.next_power_of_2(block_n)


def _pipeline_blocks(spatial_dim, batch_dim, channels):
    """Picks BLOCK_S and the (batch, s-tile) unit partition for partial/apply.

    The goal is a total program count of ~TARGET_PROGRAM_WAVES 48-SPU waves; a larger BLOCK_S means
    fewer programs (less program tax) and a smaller one means more parallelism. When the unit count
    exceeds the wave target the in-kernel stride loop catches it. Non-divisible spatial sizes take
    the masked form with lanes capped at MASKED_LANE_CAP (the safe domain for the gcu400
    masked+other-large-lanes silent-wrong-value trap; no masked load here carries other).
    """
    wave_target = max(1, (TARGET_PROGRAM_WAVES * SPU_COUNT) // max(channels, 1))

    def plan(block_cap):
        block_s = min(block_cap, triton.next_power_of_2(max(2, spatial_dim)))
        if spatial_dim % block_s != 0:
            block_s = min(block_s, MASKED_LANE_CAP)
        s_tiles = triton.cdiv(spatial_dim, block_s)
        units = batch_dim * s_tiles
        grid_p = min(units, wave_target, MAX_GRID_Y)
        return block_s, s_tiles, units, grid_p

    return plan(PARTIAL_BLOCK_CAP), plan(APPLY_BLOCK_CAP)


def _pipeline_applicable(input_3d, out_3d, weight, bias, running_mean, running_var):
    if input_3d.numel() < PIPELINE_MIN_ELEMENTS or input_3d.numel() >= 2**31:
        return False
    # The pipelined kernel assumes the spatial axis is contiguous (batch/feat strides are arbitrary and serve as scalar
    # base addresses).
    if input_3d.stride(2) != 1 or out_3d.stride(2) != 1:
        return False
    small_tensors = [weight, bias, running_mean, running_var]
    for tensor in small_tensors:
        if tensor is not None and not tensor.is_contiguous():
            return False
    return True


def _bn_direct_launch(
    input_3d,
    weight,
    bias,
    running_mean,
    running_var,
    save_mean,
    save_invstd,
    out_3d,
    training,
    momentum,
    eps,
    has_running,
):
    """Large contiguous tensors take the partial+apply two-kernel path; the rest the single-CTA fused kernel."""
    batch_dim, feat_dim, spatial_dim = input_3d.shape
    numel_per_c = batch_dim * spatial_dim
    with torch_device_fn.device(input_3d.device):
        if training and _pipeline_applicable(
            input_3d, out_3d, weight, bias, running_mean, running_var
        ):
            (p_block, p_tiles, p_units, p_grid_p), (
                a_block,
                a_tiles,
                a_units,
                a_grid_p,
            ) = _pipeline_blocks(spatial_dim, batch_dim, feat_dim)
            partial_sum = torch.empty(
                (feat_dim, p_grid_p),
                dtype=torch.float32,
                device=input_3d.device,
            )
            partial_sumsq = torch.empty_like(partial_sum)
            _nbn_partial_kernel[(feat_dim, p_grid_p)](
                input_3d,
                partial_sum,
                partial_sumsq,
                spatial_dim,
                input_3d.stride(0),
                input_3d.stride(1),
                S_TILES=p_tiles,
                UNITS=p_units,
                GRID_P=p_grid_p,
                BLOCK_S=p_block,
                EVEN_S=spatial_dim % p_block == 0,
                num_warps=PARTIAL_WARPS,
            )
            _nbn_apply_kernel[(feat_dim, a_grid_p)](
                input_3d,
                out_3d,
                weight,
                bias,
                save_mean,
                save_invstd,
                running_mean,
                running_var,
                partial_sum,
                partial_sumsq,
                input_3d.stride(0),
                input_3d.stride(1),
                out_3d.stride(0),
                out_3d.stride(1),
                numel_per_c,
                spatial_dim,
                momentum,
                eps,
                IS_TRAIN=True,
                HAS_RUNNING=has_running,
                HAS_WEIGHT=weight is not None,
                HAS_BIAS=bias is not None,
                S_TILES=a_tiles,
                UNITS=a_units,
                GRID_P=a_grid_p,
                PARTS=p_grid_p,
                PARTS_P2=triton.next_power_of_2(max(2, p_grid_p)),
                BLOCK_S=a_block,
                EVEN_S=spatial_dim % a_block == 0,
                num_warps=APPLY_WARPS,
            )
            return
        if not training and _pipeline_applicable(
            input_3d, out_3d, weight, bias, running_mean, running_var
        ):
            # Inference mode needs no statistics pass: the partial pointer is not touched in the IS_TRAIN=False branch
            # (eliminated at compile time); pass a save_mean placeholder to avoid an extra allocation.
            (_, _, _, p_grid_p), (a_block, a_tiles, a_units, a_grid_p) = (
                _pipeline_blocks(spatial_dim, batch_dim, feat_dim)
            )
            _nbn_apply_kernel[(feat_dim, a_grid_p)](
                input_3d,
                out_3d,
                weight,
                bias,
                save_mean,
                save_invstd,
                running_mean,
                running_var,
                save_mean,
                save_mean,
                input_3d.stride(0),
                input_3d.stride(1),
                out_3d.stride(0),
                out_3d.stride(1),
                numel_per_c,
                spatial_dim,
                momentum,
                eps,
                IS_TRAIN=False,
                HAS_RUNNING=False,
                HAS_WEIGHT=weight is not None,
                HAS_BIAS=bias is not None,
                S_TILES=a_tiles,
                UNITS=a_units,
                GRID_P=a_grid_p,
                PARTS=p_grid_p,
                PARTS_P2=triton.next_power_of_2(max(2, p_grid_p)),
                BLOCK_S=a_block,
                EVEN_S=spatial_dim % a_block == 0,
                num_warps=APPLY_WARPS,
            )
            return
        block_m, block_n = _choose_tile(batch_dim, spatial_dim)
        _nbn_fused_kernel[(feat_dim,)](
            input_3d,
            weight,
            bias,
            save_mean,
            save_invstd,
            out_3d,
            running_mean,
            running_var,
            batch_dim,
            spatial_dim,
            *input_3d.stride(),
            *out_3d.stride(),
            momentum,
            eps,
            IS_TRAIN=training,
            HAS_RUNNING=has_running,
            BLOCK_M=block_m,
            BLOCK_N=block_n,
            LOOP_STAGES=LOOP_STAGES,
            WELFORD_MODE=WELFORD_MODE,
            num_warps=NUM_WARPS,
            num_stages=LAUNCH_STAGES,
        )


def _prepare_out_views(input, out, save_mean, save_invstd):
    """Fixes the output shape per the aten out semantics; returns (input_3d, out_3d, feat_dim)."""
    input_3d = make_3d_for_bn(input)
    out_3d = make_3d_for_bn(out)
    feat_dim = input_3d.shape[1]
    if SHAPE_CHECK:
        if out_3d.shape != input_3d.shape:
            out.resize_as_(input)
            out_3d = make_3d_for_bn(out)
        if save_mean.numel() != feat_dim:
            save_mean.resize_((feat_dim,))
        if save_invstd.numel() != feat_dim:
            save_invstd.resize_((feat_dim,))
    return input_3d, out_3d, feat_dim


def _native_batch_norm_legit(
    input: Tensor,
    weight,
    bias,
    running_mean: Tensor,
    running_var: Tensor,
    training: bool,
    momentum: float,
    eps: float,
):
    """Batch normalization with in-place running statistics updates."""
    logger.debug("GEMS_ENFLAME _NATIVE_BATCH_NORM_LEGIT")
    output, save_mean, save_invstd = batch_norm(
        input,
        weight=weight,
        bias=bias,
        running_mean=running_mean,
        running_var=running_var,
        training=training,
        momentum=momentum,
        eps=eps,
    )
    return output, save_mean, save_invstd


def _native_batch_norm_legit_no_stats(
    input: Tensor,
    weight,
    bias,
    training: bool,
    momentum: float,
    eps: float,
):
    """Batch normalization without persistent running statistics."""
    logger.debug("GEMS_ENFLAME _NATIVE_BATCH_NORM_LEGIT_NO_STATS")
    if not training:
        raise RuntimeError("Expected has_running_mean to be true, but got false.")
    channels = input.shape[1]
    running_mean = torch.zeros(channels, dtype=input.dtype, device=input.device)
    running_var = torch.ones(channels, dtype=input.dtype, device=input.device)
    return batch_norm(
        input,
        weight=weight,
        bias=bias,
        running_mean=running_mean,
        running_var=running_var,
        training=True,
        momentum=momentum,
        eps=eps,
    )


def _copy_outputs(result, out, save_mean, save_invstd):
    result_out, result_mean, result_invstd = result
    out.resize_as_(result_out).copy_(result_out)
    save_mean.resize_as_(result_mean).copy_(result_mean)
    save_invstd.resize_as_(result_invstd).copy_(result_invstd)
    return out, save_mean, save_invstd


def _direct_out_ready(out, out_3d, save_mean, save_invstd):
    """The direct-write path requires out_3d to be a view of out (flatten did not copy) with contiguous stats."""
    if out_3d.data_ptr() != out.data_ptr():
        return False
    return save_mean.is_contiguous() and save_invstd.is_contiguous()


def _native_batch_norm_legit_out(
    input: Tensor,
    weight,
    bias,
    running_mean: Tensor,
    running_var: Tensor,
    training: bool,
    momentum: float,
    eps: float,
    *,
    out: Tensor,
    save_mean: Tensor,
    save_invstd: Tensor,
):
    logger.debug("GEMS_ENFLAME _NATIVE_BATCH_NORM_LEGIT_OUT")
    input_3d, out_3d, _ = _prepare_out_views(input, out, save_mean, save_invstd)
    if input_3d.numel() > 0 and _direct_out_ready(out, out_3d, save_mean, save_invstd):
        _bn_direct_launch(
            input_3d,
            weight,
            bias,
            running_mean,
            running_var,
            save_mean,
            save_invstd,
            out_3d,
            training,
            momentum,
            eps,
            has_running=training and running_mean is not None,
        )
        return out, save_mean, save_invstd
    result = _native_batch_norm_legit(
        input,
        weight,
        bias,
        running_mean,
        running_var,
        training,
        momentum,
        eps,
    )
    return _copy_outputs(result, out, save_mean, save_invstd)


def _native_batch_norm_legit_no_stats_out(
    input: Tensor,
    weight,
    bias,
    training: bool,
    momentum: float,
    eps: float,
    *,
    out: Tensor,
    save_mean: Tensor,
    save_invstd: Tensor,
):
    logger.debug("GEMS_ENFLAME _NATIVE_BATCH_NORM_LEGIT_NO_STATS_OUT")
    if not training:
        raise RuntimeError("Expected has_running_mean to be true, but got false.")
    input_3d, out_3d, _ = _prepare_out_views(input, out, save_mean, save_invstd)
    if input_3d.numel() > 0 and _direct_out_ready(out, out_3d, save_mean, save_invstd):
        _bn_direct_launch(
            input_3d,
            weight,
            bias,
            None,
            None,
            save_mean,
            save_invstd,
            out_3d,
            True,
            momentum,
            eps,
            has_running=False,
        )
        return out, save_mean, save_invstd
    result = _native_batch_norm_legit_no_stats(
        input, weight, bias, training, momentum, eps
    )
    return _copy_outputs(result, out, save_mean, save_invstd)


